import{_ as r,C as t,c as n,o as s,aj as l,G as a,w as h}from"./chunks/framework.Bfdr4H5E.js";const u="/sk/images/The-Development-Stages.webp",b=JSON.parse('{"title":"The Development Stages","description":"","frontmatter":{"outline":"deep","prev":{"text":"Deliberate Practice Tools and Techniques","link":"/trading-with-pav/deliberate-practice-tools-and-techniques"},"next":{"text":"Taking Action – Alternate Strategies","link":"/trading-with-pav/taking-action-alternate-strategies"}},"headers":[],"relativePath":"trading-with-pav/the-development-stages.md","filePath":"trading-with-pav/the-development-stages.md"}'),d={name:"trading-with-pav/the-development-stages.md"};function c(m,e,p,g,f,v){const i=t("GraphComment"),o=t("ClientOnly");return s(),n("div",null,[e[0]||(e[0]=l('<h1 id="the-development-stages" tabindex="-1">The Development Stages <a class="header-anchor" href="#the-development-stages" aria-label="Permalink to &quot;The Development Stages&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#taking-action">Taking Action</a></li><li><a href="#the-development-stages-1">The Development Stages</a><ul><li><a href="#stage-1-–-establish-your-foundation">Stage 1 – Establish Your Foundation</a></li><li><a href="#stage-2-–-simulator-environment">Stage 2 – Simulator Environment</a></li><li><a href="#stage-3-–-live-environment-–-minimum-size">Stage 3 – Live Environment – Minimum Size</a></li><li><a href="#stage-4-–-live-environment-–-increasing-size">Stage 4 – Live Environment – Increasing Size</a></li></ul></li><li><a href="#as-you-progress">As You Progress…</a><ul><li><a href="#note">NOTE:</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="taking-action" tabindex="-1">Taking Action <a class="header-anchor" href="#taking-action" aria-label="Permalink to &quot;Taking Action&quot;">​</a></h2><p>Our aim in this article is to put in place a process to follow as you progress from wherever you are right now, towards consistent profitability.</p><p>If you’re a novice, start at the beginning. If you’re experienced, start at the beginning as well, comforted by the fact that you’ll progress faster.</p><p>As with anything I present, feel free to adapt it to your own needs. Although I will caution you; there are no short-cuts in this game. Learning is a process. Cut out or amend steps at your own risk.</p><h2 id="the-development-stages-1" tabindex="-1">The Development Stages <a class="header-anchor" href="#the-development-stages-1" aria-label="Permalink to &quot;The Development Stages&quot;">​</a></h2><p>We’ll start by defining several stages of development.</p><p><img src="'+u+'" alt="The-Development-Stages"> <em>Development Stages</em></p><p>We establish our foundation; we learn to trade in a simulated environment; we learn to trade live with minimum size; and we learn to trade live with increasing size.</p><p>Each stage must be clearly defined, with targets to achieve prior to advancing to the next stage. Let’s do that now.</p><h3 id="stage-1-–-establish-your-foundation" tabindex="-1">Stage 1 – Establish Your Foundation <a class="header-anchor" href="#stage-1-–-establish-your-foundation" aria-label="Permalink to &quot;Stage 1 – Establish Your Foundation&quot;">​</a></h3><h4 id="foundation-knowledge" tabindex="-1">Foundation Knowledge: <a class="header-anchor" href="#foundation-knowledge" aria-label="Permalink to &quot;Foundation Knowledge:&quot;">​</a></h4><p>Read the eight volumes of YSTC Trading with Price Action Volume.</p><h4 id="setup" tabindex="-1">Setup: <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup:&quot;">​</a></h4><ul><li>Choose your market and timeframe.</li><li>Document your <strong>Trading Plan</strong> and <strong>Procedures Manual</strong> – <a href="/sk/trading-with-pav/trading-plan-explanatory-notes/">Article 80</a> and <a href="/sk/trading-with-pav/procedures-manual/">81</a>.</li><li>Establish your <strong>Logs</strong> and <strong>Journals</strong> – <a href="/sk/trading-with-pav/additional-documentation/">Article 89</a>.</li><li>Set up your <strong>Trading Platform</strong> – <a href="/sk/trading-with-pav/trading-platform-setup/">Article 79</a>.</li></ul><h4 id="study-price-action-–-market-structure-and-setup-areas" tabindex="-1">Study price action – market structure and setup areas: <a class="header-anchor" href="#study-price-action-–-market-structure-and-setup-areas" aria-label="Permalink to &quot;Study price action – market structure and setup areas:&quot;">​</a></h4><ol><li>Print historical charts (all three timeframes) for 100 trading sessions.</li><li>Take the charts for one session, and study price action with the benefit of hindsight perfection. <ul><li>Where were the higher timeframe S/R levels? Mark them on the higher and trading timeframe charts, only to the point at which they become irrelevant. Then add new levels as they come into play.</li><li>Study the nature of price movement within the structure. Define the changes of trend. How did it trend? Is it moving with ease, or facing opposing order-flow throughout? What does this tell you about the bullish or bearish sentiment of market participants? What clues were provided that could have alerted you to the nature of price movement? Note any significant changes in structure, such as key breakout points, or areas of smooth price trend vs congestion. Look for clues that could have alerted you to the changing environment. Record observations on the charts. Record significant observations within your Lessons Learnt Journal.</li><li>Identify setup areas and mark them on the chart. How could you have identified these in advance? Where are the signs of strength and weakness leading into the area? How did price act within the area, to provide clues as to potential success or failure? <ul><li>i) Study price interaction with S/R. What clues did price offer regarding potential test, breakout failure or breakout pullback opportunity? How could you have seen this in advance?</li><li>ii) Study pullbacks. What price action with volume led to a simple, single-swing pullback? What price action volume led to complex (multiple swing or extended duration) pullbacks?</li></ul></li><li>Don’t worry about trades at this stage. Simply make observations of market structure, the nature of price movement and setup areas.</li></ul></li><li>Place the charts in your market structure journal.</li><li>Repeat steps 2 and 3 for all 100 sessions.</li></ol><h4 id="simulator-practice-–-market-structure-and-setup-areas" tabindex="-1">Simulator practice – market structure and setup areas: <a class="header-anchor" href="#simulator-practice-–-market-structure-and-setup-areas" aria-label="Permalink to &quot;Simulator practice – market structure and setup areas:&quot;">​</a></h4><ol><li>Trade a simulator (demo) <a href="https://www.tradingview.com/gopro/?share_your_love=YSTC" target="_blank" rel="noreferrer">TradingView</a> platform with live or recorded market data.</li><li>Follow price action and volume throughout the session while carrying out your initial and ongoing analysis processes. Make notes within your trading log throughout the session. Print (or screen capture) charts if necessary to record price action at the time of your trading log observations.</li><li>Do NOT concern yourself with trade entry, management and exit. Just aim to follow price; maintaining your assessment of likely future trend direction and areas of trade opportunity.</li><li>Following each session, conduct your post-session review process in order to compare your actual performance with hindsight-perfect performance.</li><li>Print charts and make notes for your journals – lessons learnt and market structure.</li><li>Repeat for as long as necessary to feel comfortable with the process. I recommend no less than two weeks (10 sessions). Make use of market replay if time is available, in order to reinforce any lessons learnt and build your intuitive mental model of the markets and price action and volume.</li></ol><h4 id="study-price-action-–-trade-opportunity" tabindex="-1">Study price action – trade opportunity: <a class="header-anchor" href="#study-price-action-–-trade-opportunity" aria-label="Permalink to &quot;Study price action – trade opportunity:&quot;">​</a></h4><ol><li>Return to your 100 session chart printouts.</li><li>Having become comfortable with identifying market structure and setup opportunities, you will now consider trade entry and management. Start with the printouts for the first session. <ul><li>a) Review the previously identified setups.</li><li>b) How should you have traded these setup areas (in broad principle only)? Where was the ideal entry point? Consider the nature of price movement (smooth or choppy with much candle overlap, for example) – how could that have influenced your trade entry decision? How should you have managed the trade, with the benefit of hindsight? Should you have scratched? When should you have moved stops to breakeven, or beyond? Where was the ideal exit? What clues were provided with the price action to lead to this hindsight perfect trade?</li></ul></li><li>Repeat step 2 for all sessions.</li><li>Return the charts to your Market Structure Journal for future study.</li></ol><h4 id="simulator-practice-market-replay-–-trade-opportunity" tabindex="-1">Simulator practice (market replay) – trade opportunity: <a class="header-anchor" href="#simulator-practice-market-replay-–-trade-opportunity" aria-label="Permalink to &quot;Simulator practice (market replay) – trade opportunity:&quot;">​</a></h4><ul><li>For each of the previously recorded simulator sessions: <ul><li>a) Replay market data with the intent of again conducting your initial and ongoing analysis, this time also trading each of the setups.</li><li>b) Following each setup, pause to review your attempts to trade it. Where did you correctly read the market sentiment and make correct trading decisions? Where should your decisions have been different? Record any lessons in your lessons learnt journal.</li></ul></li></ul><h4 id="target-for-advancement-to-stage-2" tabindex="-1">Target for Advancement to Stage 2: <a class="header-anchor" href="#target-for-advancement-to-stage-2" aria-label="Permalink to &quot;Target for Advancement to Stage 2:&quot;">​</a></h4><ol><li>Minimum 100 historical sessions reviewed in hindsight – market structure and setup areas.</li><li>Minimum 2 weeks simulator trading – market structure and setup areas – NO TRADES.</li><li>Minimum 100 historical sessions reviewed in hindsight – trade opportunity.</li><li>Minimum 2 weeks simulator trading (market replay) – trade opportunity</li></ol><p>Yes, this will take at least a month! Or possibly a lot longer if you don’t have 100 sessions of historical data! You may wish to consider similar markets to make up the numbers, but I recommend at least 50 sessions from the actual markets you will trade.</p><p>Be patient. You will learn a lot during this process.</p><h3 id="stage-2-–-simulator-environment" tabindex="-1">Stage 2 – Simulator Environment <a class="header-anchor" href="#stage-2-–-simulator-environment" aria-label="Permalink to &quot;Stage 2 – Simulator Environment&quot;">​</a></h3><h4 id="initial-benchmark" tabindex="-1">Initial Benchmark: <a class="header-anchor" href="#initial-benchmark" aria-label="Permalink to &quot;Initial Benchmark:&quot;">​</a></h4><ol><li>Review the Pre, During and Post-Session Routines – <a href="/sk/trading-with-pav/routines-pre-session/">Article 83</a>, <a href="/sk/trading-with-pav/routines-during-session/">84</a>, <a href="/sk/trading-with-pav/routines-post-session/">85</a>.</li><li>Commence trading the strategy as if live, but within the safety of a simulator (demo) environment.</li><li>Carry out all daily routines for one week. Do not concern yourself with results, although all trading must be conducted in as professional a manner as possible. We are not playing here! This is serious business!</li><li>Record your trading stats. These set your initial benchmark. You will most likely not have achieved profitable results. Do not be concerned. This is merely your starting point.</li></ol><h4 id="improvement" tabindex="-1">Improvement: <a class="header-anchor" href="#improvement" aria-label="Permalink to &quot;Improvement:&quot;">​</a></h4><ol><li>Continue trading, aiming for gradual improvements through an effective review process.</li><li>Refer to the later section on Challenges and Difficulties, if necessary.</li><li>Repeat until achieving profitable results in each of four consecutive weeks.</li></ol><h4 id="target-for-advancement-to-stage-3" tabindex="-1">Target for Advancement to Stage 3: <a class="header-anchor" href="#target-for-advancement-to-stage-3" aria-label="Permalink to &quot;Target for Advancement to Stage 3:&quot;">​</a></h4><ul><li>Profitable results in each of four consecutive weeks, within the simulator (demo) environment.</li></ul><h3 id="stage-3-–-live-environment-–-minimum-size" tabindex="-1">Stage 3 – Live Environment – Minimum Size <a class="header-anchor" href="#stage-3-–-live-environment-–-minimum-size" aria-label="Permalink to &quot;Stage 3 – Live Environment – Minimum Size&quot;">​</a></h3><h4 id="initial-benchmark-1" tabindex="-1">Initial Benchmark: <a class="header-anchor" href="#initial-benchmark-1" aria-label="Permalink to &quot;Initial Benchmark:&quot;">​</a></h4><ol><li>Commence trading the strategy in a live market environment, with the minimum position size possible for each of your two part positions.</li><li>Carry out all daily routines for one week.</li><li>STOP TRADING if you lose 10% of your trading funds. Something is most likely NOT going right. Conduct a thorough review and return to the simulator environment. Note: You must be financially able to afford the loss of this 10% of your trading funds. If not, do not commence stage 3 until having saved a larger account balance. Alternatively, consider moving to a market that allows smaller accounts and smaller position sizes.</li><li>Record your trading stats. These set your initial benchmark. You will most likely not have achieved profitable results. Do not be concerned. This is merely your starting point.</li></ol><h4 id="improvement-1" tabindex="-1">Improvement: <a class="header-anchor" href="#improvement-1" aria-label="Permalink to &quot;Improvement:&quot;">​</a></h4><ol><li>Continue trading, aiming for gradual improvements through an effective review process.</li><li>Refer to the later section on Challenges and Difficulties, if necessary.</li><li>There is to be no consideration for increasing position size until achieving profitable results in each of four consecutive weeks. Size increase though is not compulsory. Remain at minimum size for as long as you need.</li></ol><h4 id="target-for-advancement-to-stage-4" tabindex="-1">Target for Advancement to Stage 4: <a class="header-anchor" href="#target-for-advancement-to-stage-4" aria-label="Permalink to &quot;Target for Advancement to Stage 4:&quot;">​</a></h4><ul><li>Profitable results in each of four consecutive weeks, within the live market environment, with minimum position size.</li></ul><h3 id="stage-4-–-live-environment-–-increasing-size" tabindex="-1">Stage 4 – Live Environment – Increasing Size <a class="header-anchor" href="#stage-4-–-live-environment-–-increasing-size" aria-label="Permalink to &quot;Stage 4 – Live Environment – Increasing Size&quot;">​</a></h3><h4 id="proof-of-ability" tabindex="-1">Proof of Ability: <a class="header-anchor" href="#proof-of-ability" aria-label="Permalink to &quot;Proof of Ability:&quot;">​</a></h4><ol><li>Return to a simulated environment, trading the increased position size.</li><li>Carry out all daily routines for one week.</li><li>Do not transition to a live environment until demonstrating a profitable week. If you fail to achieve profitability, consider either returning to the previous size for additional time, or attempting a second week. If the second week is not profitable you must remain at the original size. You may only progress to the live environment if the combined fortnight is profitable.</li></ol><h4 id="trading-increased-size" tabindex="-1">Trading Increased Size: <a class="header-anchor" href="#trading-increased-size" aria-label="Permalink to &quot;Trading Increased Size:&quot;">​</a></h4><ol><li>Continue trading, aiming for gradual improvements through an effective review process.</li><li>Refer to the later articles on Challenges and Difficulties, if necessary.</li><li>There is to be no consideration for further increases of position size until achieving profitable results in each of four consecutive weeks at each size level. Size increase though is not compulsory. Remain at the current size for as long as you need.</li></ol><h4 id="target-for-further-size-increases" tabindex="-1">Target for Further Size Increases: <a class="header-anchor" href="#target-for-further-size-increases" aria-label="Permalink to &quot;Target for Further Size Increases:&quot;">​</a></h4><ul><li>Profitable results in each of four consecutive weeks, within the live market environment, with the current position size.</li></ul><h2 id="as-you-progress" tabindex="-1">As You Progress… <a class="header-anchor" href="#as-you-progress" aria-label="Permalink to &quot;As You Progress…&quot;">​</a></h2><h3 id="note" tabindex="-1">NOTE: <a class="header-anchor" href="#note" aria-label="Permalink to &quot;NOTE:&quot;">​</a></h3><ol><li>All size increases must involve a gradual increase, not a large jump. There is no hurry. The number one priority is to ensure survival at each level, prior to advancing to larger size.</li><li>Throughout this development plan I have referred to trading for a week. Obviously different weeks will have different numbers of trades. The intent is that each week provides a minimum of 20 trades. If your week does not provide this, carry this week over to include the next. That is, group the trades from the fortnight and consider that as a single week, for the purposes of our development plan.</li></ol><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',53)),a(o,null,{default:h(()=>[a(i)]),_:1})])}const k=r(d,[["render",c]]);export{b as __pageData,k as default};
